SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @CommitChanges bit = 1; -- Set to 0 when a validation-only rollback is required.
DECLARE @CreatedByUserAccountId bigint;
DECLARE @ImportedByEmployeeId bigint;
SELECT TOP (1) @CreatedByUserAccountId = ua.UserAccountId, @ImportedByEmployeeId = ua.EmployeeId
FROM dbo.UserAccount AS ua
WHERE ua.AccountType = 'EMPLOYEE' AND ua.AccountStatus = 'ACTIVE' AND ua.EmployeeId IS NOT NULL
ORDER BY ua.UserAccountId;
IF @CreatedByUserAccountId IS NULL OR @ImportedByEmployeeId IS NULL
