INSERT dbo.Dealer (DealerCode, DealerName, ShortName, Area, DealerCondition)
SELECT s.DealerCode, s.DealerName, s.DealerName, s.Area, 'ACTIVE'
FROM #DealerStage AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.Dealer AS d WHERE d.DealerCode = s.DealerCode);

