INSERT dbo.Product (ProductCode, ProductName, CategoryLevel1, CategoryLevel2, IsActive)
SELECT s.ProductCode, s.ProductName, s.CategoryLevel1, s.CategoryLevel2, 1
FROM #ProductStage AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.Product AS p WHERE p.ProductCode = s.ProductCode);

