CREATE TABLE #OpeningBatchMap (DataMonth char(6) NOT NULL PRIMARY KEY, ImportBatchId bigint NOT NULL);
INSERT dbo.ImportBatch (ImportType,DataMonth,DataDate,OriginalFileName,StoredFilePath,FileHash,FileSize,ImportStatus,TotalRowCount,SuccessRowCount,ErrorRowCount,ImportedByEmployeeId)
SELECT 'OPENING_INVENTORY', m.DataMonth, NULL, N'TEST_202510-202609期初.xlsx', N'[manual SQL test data]', CONCAT('MANUAL-OPENING-',m.DataMonth), 10026160, 'Official', COUNT_BIG(*), COUNT_BIG(*), 0, @ImportedByEmployeeId
FROM #OpeningStage AS m
WHERE NOT EXISTS (SELECT 1 FROM dbo.ImportBatch b WHERE b.ImportType='OPENING_INVENTORY' AND b.DataMonth=m.DataMonth AND b.OriginalFileName=N'TEST_202510-202609期初.xlsx' AND b.ImportStatus='Official')
GROUP BY m.DataMonth;
INSERT #OpeningBatchMap (DataMonth,ImportBatchId)
SELECT s.DataMonth, MAX(b.ImportBatchId)
FROM (SELECT DISTINCT DataMonth FROM #OpeningStage) s
JOIN dbo.ImportBatch b ON b.ImportType='OPENING_INVENTORY' AND b.DataMonth=s.DataMonth AND b.OriginalFileName=N'TEST_202510-202609期初.xlsx' AND b.ImportStatus='Official'
GROUP BY s.DataMonth;
INSERT dbo.MonthlyOpeningInventoryDetail (ImportBatchId,SourceRowNumber,DealerId,ProductId,OpeningQuantity)
SELECT bm.ImportBatchId,s.SourceRowNumber,d.DealerId,p.ProductId,s.OpeningQuantity
FROM #OpeningStage s JOIN #OpeningBatchMap bm ON bm.DataMonth=s.DataMonth JOIN dbo.Dealer d ON d.DealerCode=s.DealerCode JOIN dbo.Product p ON p.ProductCode=s.ProductCode
WHERE NOT EXISTS (SELECT 1 FROM dbo.MonthlyOpeningInventoryDetail x WHERE x.ImportBatchId=bm.ImportBatchId AND x.DealerId=d.DealerId AND x.ProductId=p.ProductId);

