CREATE TABLE #SellInBatchMap (DataMonth char(6) NOT NULL PRIMARY KEY,ImportBatchId bigint NOT NULL);
INSERT dbo.ImportBatch (ImportType,DataMonth,DataDate,OriginalFileName,StoredFilePath,FileHash,FileSize,ImportStatus,TotalRowCount,SuccessRowCount,ErrorRowCount,ImportedByEmployeeId)
SELECT 'SELL_IN',s.DataMonth,NULL,N'TEST_2026年1-6月in_out.xlsx',N'[manual SQL test data]',CONCAT('MANUAL-SELLIN-',s.DataMonth),8380862,'Official',COUNT_BIG(*),COUNT_BIG(*),0,@ImportedByEmployeeId
FROM #SellInStage s
WHERE NOT EXISTS (SELECT 1 FROM dbo.ImportBatch b WHERE b.ImportType='SELL_IN' AND b.DataMonth=s.DataMonth AND b.OriginalFileName=N'TEST_2026年1-6月in_out.xlsx' AND b.ImportStatus='Official')
GROUP BY s.DataMonth;
INSERT #SellInBatchMap (DataMonth,ImportBatchId)
SELECT s.DataMonth,MAX(b.ImportBatchId) FROM (SELECT DISTINCT DataMonth FROM #SellInStage) s JOIN dbo.ImportBatch b ON b.ImportType='SELL_IN' AND b.DataMonth=s.DataMonth AND b.OriginalFileName=N'TEST_2026年1-6月in_out.xlsx' AND b.ImportStatus='Official' GROUP BY s.DataMonth;
INSERT dbo.SellInTransaction (ImportBatchId,SourceRowNumber,DealerId,ProductId,SalesDocumentNo,SalesDocumentItemNo,InvoiceNo,OrderDate,BillingDate,InvoiceDate,InventoryEffectiveDate,Quantity,TransactionType,TransactionStatus,ReviewStatus)
SELECT bm.ImportBatchId,s.SourceRowNumber,d.DealerId,p.ProductId,s.SalesDocumentNo,s.SalesDocumentItemNo,NULL,s.TransactionDate,s.TransactionDate,NULL,s.TransactionDate,s.Quantity,s.TransactionType,'VALID','APPROVED'
FROM #SellInStage s JOIN #SellInBatchMap bm ON bm.DataMonth=s.DataMonth JOIN dbo.Dealer d ON d.DealerCode=s.DealerCode JOIN dbo.Product p ON p.ProductCode=s.ProductCode
WHERE NOT EXISTS (SELECT 1 FROM dbo.SellInTransaction x WHERE x.SalesDocumentNo=s.SalesDocumentNo AND x.SalesDocumentItemNo=s.SalesDocumentItemNo);

