CREATE TABLE #VisitMap (VisitKey varchar(100) NOT NULL PRIMARY KEY,StoreVisitId bigint NOT NULL);
INSERT dbo.StoreVisit (DealerId,DealerLocationId,DealerAssignmentId,EntrySourceType,ReportDateTime,RecordStatus,CreatedByUserAccountId)
SELECT d.DealerId,l.DealerLocationId,NULL,'EMPLOYEE',DATEADD(second,43200+s.SlotNo,CAST(s.VisitDate AS datetime2(0))),'ACTIVE',@CreatedByUserAccountId
FROM #VisitStage s
JOIN dbo.Dealer d ON d.DealerCode=s.DealerCode
JOIN dbo.DealerLocation l ON l.DealerId=d.DealerId AND l.IsPrimary=1 AND l.IsActive=1
WHERE NOT EXISTS (SELECT 1 FROM dbo.StoreVisit v WHERE v.DealerId=d.DealerId AND v.DealerLocationId=l.DealerLocationId AND v.ReportDateTime=DATEADD(second,43200+s.SlotNo,CAST(s.VisitDate AS datetime2(0))) AND v.EntrySourceType='EMPLOYEE');
INSERT #VisitMap (VisitKey,StoreVisitId)
SELECT s.VisitKey,v.StoreVisitId
FROM #VisitStage s
JOIN dbo.Dealer d ON d.DealerCode=s.DealerCode
JOIN dbo.DealerLocation l ON l.DealerId=d.DealerId AND l.IsPrimary=1 AND l.IsActive=1
JOIN dbo.StoreVisit v ON v.DealerId=d.DealerId AND v.DealerLocationId=l.DealerLocationId AND v.ReportDateTime=DATEADD(second,43200+s.SlotNo,CAST(s.VisitDate AS datetime2(0))) AND v.EntrySourceType='EMPLOYEE';
