INSERT dbo.StoreVisitProductDetail (StoreVisitId,ProductId,SellOutQuantity,SellOutDate,DisplayQuantity)
SELECT vm.StoreVisitId,p.ProductId,s.SellOutQuantity,s.SellOutDate,NULL
FROM #VisitDetailStage s JOIN #VisitMap vm ON vm.VisitKey=s.VisitKey JOIN dbo.Product p ON p.ProductCode=s.ProductCode
WHERE NOT EXISTS (SELECT 1 FROM dbo.StoreVisitProductDetail x WHERE x.StoreVisitId=vm.StoreVisitId AND x.ProductId=p.ProductId);

IF @CommitChanges = 1
BEGIN
    COMMIT TRANSACTION;
    PRINT 'Committed test data successfully.';
END
ELSE
BEGIN
    ROLLBACK TRANSACTION;
    PRINT 'Validation run only: transaction rolled back. Set @CommitChanges = 1 to import.';
END;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
